138	/**
139	 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
140	 * Opening gives the claim the sheet's next number; a voided claim keeps its number (it is never reused). While the
141	 * sheet's period numbering from date is set and its today is on or after it, opening instead gives the claim the next
142	 * number within the period containing its due-by (P1-1, P1-2, ...), or within the claims in no period (X-1, ...).
143	 * Opening, settling and voiding are refused (400) to a role the sheet's permission matrix does not allow them.
144	 * Opening records the user who opened it; that user cannot settle it (four eyes). Nor can the user who last edited
145	 * it (through its editor or its row's amount entry) settle or approve it. A deferred claim cannot be settled.
146	 * Settling fixes the claim's due at the greater of the sheet's floor in force on its date and its figure — at its person's grade's rate in force on the claim's date,
147	 * rounded by its policy date, or, when a statement bound the claim, the figure it was bound to — plus the late charge it has then, if overdue, frozen in; with no
148	 * figure it stays live. A clerk settling a claim whose due is above the sheet's clerk limit (a due of n/a is within any
149	 * limit) makes it PENDING instead, live and unfixed. A claim with no proofs whose due is above the proof threshold in force on its date —
150	 * its person's grade's own, when that grade has one then, else the sheet's — is refused settling or approving — before the clerk limit is considered, so it never goes PENDING.
151	 * A claim with an empty note whose due (as shown now) is above the sheet's note threshold in force on its date is refused opening.
152	 * Opening a claim due by a date in a period with a cap is refused while its person already has that many OPEN or PENDING
153	 * claims due by a date in that period. Only a steward approves a PENDING claim (fixing its due at its live
154	 * figure, plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
155	 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
156	 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
157	 * Only a steward voids a SETTLED claim, and only while the sheet's today is within 7 days of its settlement (the
158	 * status log's latest SETTLED date); it keeps its number and its frozen due, which leaves every total.
159	 * While the sheet's void reasons list is not empty, a void is refused (400) without a reason chosen from it; a reason
160	 * not on the list is always refused.
161	 * Deleting sets a DRAFT claim aside as DELETED (counting nowhere); restoring makes it a DRAFT again, only while the
162	 * sheet's today is the day it was deleted (the status log's latest DELETED date).
163	 */
164	public class ApplyClaimAction {
165	
166	    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a SETTLED claim. */
167	    static final int VOID_SETTLED_DAYS = 7;
168	
169	    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
170	            @Val ClaimActionRequest request, SheetRepository sheets,
171	            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
172	            VoidReasonRepository voidReasons, ClaimRepository claims, ClaimLogRepository logs, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
173	        ClaimAction found = ClaimAction.of(action);
174	        if (found == null) {
175	            throw new InvalidClaimException("No such claim action: " + action);
176	        }
177	        if (!found.allowedFrom(claim.status())) {
178	            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
179	        }
180	        if ((found == ClaimAction.OPEN || found == ClaimAction.SETTLE || found == ClaimAction.VOID)
181	                && !settings.find(claim.sheetId()).may(user, action)) {
182	            throw new InvalidClaimException("The user's role is not allowed to " + action + " a claim.");
183	        }
184	        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
185	            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
186	        }
187	        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
188	            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
189	        }
190	        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
191	            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
192	        }
193	        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE)
194	                && user.equals(claims.editedBy(claim.sheetId(), claim.id()))) {
195	            throw new InvalidClaimException("The user who last edited a claim cannot " + action + " it.");
196	        }
197	        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
198	                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
199	            throw new InvalidClaimException("Only a steward can " + action + " a pending claim.");
200	        }
201	        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
202	            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
203	        }
204	        if (found == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
205	            if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
206	                throw new InvalidClaimException("Only a steward can void a settled claim.");
207	            }
208	            LocalDate settledOn = logs.find(claim.sheetId(), claim.id()).stream()
209	                    .filter((l) -> l.status() == ClaimStatus.SETTLED).map(ClaimLogLine::date)
210	                    .reduce((a, b) -> b).orElse(null);
211	            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
212	                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
213	                        + " days of its settlement.");
214	            }
215	        }
216	        if (found == ClaimAction.VOID) {
217	            List<String> reasons = voidReasons.findAll(claim.sheetId());
218	            if (request.reason().isEmpty() ? !reasons.isEmpty() : !reasons.contains(request.reason())) {
219	                throw new InvalidClaimException("A void needs a reason chosen from the sheet's void reasons.");
220	            }
221	        }
222	        if (found == ClaimAction.RESTORE) {
223	            LocalDate deletedOn = logs.find(claim.sheetId(), claim.id()).stream()
224	                    .filter((l) -> l.status() == ClaimStatus.DELETED).map(ClaimLogLine::date)
225	                    .reduce((a, b) -> b).orElse(null);
226	            if (deletedOn == null || !sheets.today(claim.sheetId()).equals(deletedOn)) {
227	                throw new InvalidClaimException("A deleted claim can be restored only on the day it was deleted.");
228	            }
229	        }
230	        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
231	            throw new InvalidClaimException("A reason is required to reject a claim.");
232	        }
233	        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
234	        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
235	                && settings.dated(claim.sheetId()).needsNote(claim.date(),
236	                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
237	            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
238	        }
239	        if (found == ClaimAction.OPEN) {
240	            checkCap(claim, periods, claims);
241	        }
242	        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && claim.proofs() == 0
243	                && settings.dated(claim.sheetId()).needsProof(proofGrade(claim, people), claim.date(), due)) {
244	            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof to be "
245	                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
246	        }
247	        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
248	            found = ClaimAction.PEND;
249	            due = null;
250	        }
251	        String next = switch (found) {
252	            case OPEN -> ClaimNumbers.next(claim, sheets, settings, periods);
253	            default -> claim.number();
254	        };
255	        applied.set(found);
256	        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
257	        number.set(new ClaimNumber(next));
258	        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
259	    }
260	
261	    /** Refuses opening the claim when its period's cap on its person's OPEN and PENDING claims is already reached. */
262	    private static void checkCap(Claim claim, PeriodRepository periods, ClaimRepository claims) throws InvalidClaimException {
263	        Period period = periods.findAll(claim.sheetId()).stream()
264	                .filter((p) -> p.cap() != null && claim.dueBy() != null && p.contains(claim.dueBy())).findFirst().orElse(null);
265	        if (period == null) {
266	            return;
267	        }
268	        long open = claims.findForPerson(claim.sheetId(), claim.personId()).stream()
269	                .filter((c) -> !c.id().equals(claim.id()) && c.dueBy() != null && period.contains(c.dueBy())
270	                        && (c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING))
271	                .count();
272	        if (open >= period.cap()) {
273	            throw new InvalidClaimException("The person already has " + period.cap() + " open claims in period "
274	                    + period.name() + ": its cap.");
275	        }
276	    }
277	
278	    /** The grade whose proof threshold the claim falls under: its person's grade in force on its date (null: no person). */
279	    static String proofGrade(Claim claim, PersonRepository people) {
280	        Person person = people.find(claim.sheetId(), claim.personId());
281	        return person == null ? null : person.gradeOn(claim.date());
282	    }
283	
284	    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
285	            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
286	        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
287	    }
288	}
