383	                + " date=" + claim.date() + Claim.auditNumber(number.value())
384	                + (action == ClaimAction.RESETTLE
385	                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
386	                        : action.settles() ? " due=" + figure(claim.due()) : "")
387	                + (action == ClaimAction.REJECT ? " reason=" + request.reason() : "")
388	                + (action == ClaimAction.VOID && previous.settled() ? " reversed=" + figure(previous.value()) : "")
389	                + (action == ClaimAction.VOID && !request.reason().isEmpty() ? " reason=" + request.reason() : ""));
