472	/**
473	 * The lines that follow a change's own records: one ROLLUP line per person whose figures it moved (a person new to the
474	 * sheet counts as moved), in the order of the list, then a TOTALS line when the sheet's totals moved, then one ALERT
475	 * line per person whose due-total went from at or below the sheet's alert threshold (or no due-total) to above it, in the
476	 * order of the list.
477	 */
478	public final class RollupLines {
479	
480	    private RollupLines() {
481	    }
482	
483	    /** Records the ROLLUP and TOTALS lines for the sheet's figures moving from {@code was} to {@code now}. */
484	    public static void record(Rollup was, Rollup now, String sheetId, String user, Audit audit) {
485	        String prefix = " sheet=" + sheetId + " by=" + user;
486	        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
487	            Rollup.Figures figures = entry.getValue();
488	            if (!figures.sameAs(was.people().get(entry.getKey()))) {
489	                audit.record("ROLLUP" + prefix + " person=" + figures.name() + " claimed=" + figures.claimed()
490	                        + " due-total=" + figures.dueTotal() + " overdue-total=" + figures.overdueTotal());
491	            }
492	        }
493	        if (!now.claimedTotal().equals(was.claimedTotal()) || !now.dueTotal().equals(was.dueTotal())
494	                || !now.overdueTotal().equals(was.overdueTotal())) {
495	            audit.record("TOTALS" + prefix + " claimed-total=" + now.claimedTotal() + " due-total="
496	                    + now.dueTotal() + " overdue-total=" + now.overdueTotal());
497	        }
498	        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
499	            Rollup.Figures figures = entry.getValue();
500	            Rollup.Figures before = was.people().get(entry.getKey());
501	            if (Rollup.above(figures.dueTotal(), now.alertThreshold())
502	                    && !Rollup.above(before == null ? null : before.dueTotal(), now.alertThreshold())) {
503	                audit.record("ALERT" + prefix + " name=" + figures.name() + " due-total=" + figures.dueTotal());
504	            }
505	        }
506	    }
507	}
