529	/**
530	 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
531	 * added up, leaving out corrections; their due-total those claims' dues (live figures rounded by its policy date, plus
532	 * any late charge, at the late percent in force on each 30-day boundary, on the overdue ones, then raised to the floor in force on each claim's date) added up, at most the cap in force on the sheet's today; n/a when their grade on the sheet's today has no
533	 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). Their overdue-total
534	 * is the dues of their overdue counting claims added up (skipping n/a, not capped). The sheet's totals add these up, skipping n/a;
535	 * its due-total and overdue-total leave out the single highest and lowest person's figure when three or more have one.
536	 */
537	@Service
538	public class RollupService {
539	
540	    private static final String NA = "n/a";
541	
542	    private final PersonRepository people;
543	    private final ClaimRepository claims;
544	    private final RateRepository rates;
545	    private final SheetRepository sheets;
546	    private final SettingRepository settings;
547	
548	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
549	            SheetRepository sheets, SettingRepository settings) {
550	        this.people = people;
551	        this.claims = claims;
552	        this.rates = rates;
553	        this.sheets = sheets;
554	        this.settings = settings;
555	    }
556	
557	    /** The sheet's figures as the store holds them now. */
558	    public Rollup compute(String sheetId) {
559	        LocalDate today = sheets.today(sheetId);
560	        List<Rate> sheetRates = rates.findAll(sheetId);
561	        DatedSettings dated = settings.dated(sheetId);
562	        BigDecimal cap = dated.capOn(today);
563	        List<Claim> sheetClaims = claims.findAll(sheetId);
564	        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
565	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
566	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
567	        List<BigDecimal> dues = new ArrayList<>();
568	        List<BigDecimal> overdues = new ArrayList<>();
569	        for (Person person : people.findAll(sheetId)) {
570	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
571	            BigDecimal due = BigDecimal.ZERO.setScale(2);
572	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
573	            boolean kept = false;
574	            for (Claim claim : sheetClaims) {
575	                if (claim.personId() != person.id() || !person.counts(claim, today)) {
576	                    continue;
577	                }
578	                if (!claim.correction()) {
579	                    claimed = claimed.add(claim.amount());
580	                }
581	                kept |= claim.keepsFigure();
582	                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
583	                        dated.floorOn(claim.date()), dated.lateCharge(today, person), rounding);
584	                if (figure != null) {
585	                    kept = true;
586	                    due = due.add(figure);
587	                    if (claim.overdue(today, dated.graceFor(person, claim))) {
588	                        overdue = overdue.add(figure);
589	                    }
590	                }
591	            }
592	            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
593	            due = Cap.apply(cap, due);
594	            claimedTotal = claimedTotal.add(claimed);
595	            if (!na) {
596	                dues.add(due);
597	            }
598	            overdues.add(overdue);
599	            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due), show(overdue)));
600	        }
601	        return new Rollup(figures, show(claimedTotal), show(trimmedTotal(dues)), show(trimmedTotal(overdues)),
602	                settings.alertThreshold(sheetId));
603	    }
604	
605	    /** The figures added up, leaving out the single highest and single lowest when there are three or more. */
606	    private static BigDecimal trimmedTotal(List<BigDecimal> values) {
607	        List<BigDecimal> sorted = new ArrayList<>(values);
608	        sorted.sort(null);
609	        if (sorted.size() >= 3) {
610	            sorted = sorted.subList(1, sorted.size() - 1);
611	        }
612	        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
613	    }
