package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the user as the claim's last editor (four eyes: they cannot then settle or approve it). */
public class MarkClaimEdited {
    public void mark(@Val Claim claim, @RequestParam("user") String user, ClaimRepository claims) {
        claims.markEdited(claim.sheetId(), claim.id(), user);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just edited, with its person's name; runs only once the edit has passed every rule. */
public class AuditClaimEdited {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_EDITED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Refuses (400) an edit of a claim another user has locked by opening its editor. */
public class CheckClaimNotLocked {
    public void check(@Val Claim claim, @RequestParam("user") String user, ClaimLockRepository locks)
            throws InvalidClaimException {
        String holder = locks.lockedBy(claim.sheetId(), claim.id());
        if (holder != null && !holder.equals(user)) {
            throw new InvalidClaimException("The claim is being edited by " + holder + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuses (400) an edit of any claim that is not a DRAFT: an open claim is changed by voiding it and adding another. */
public class CheckClaimDraft {
    public void check(@Val Claim claim) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import org.springframework.stereotype.Component;

/**
 * Marks a claim just added a late entry when the period containing its due-by is soft-closed, recorded as LATE_ENTRY
 * (after its CLAIM_ADDED); nothing otherwise. Used by the claim form, the quick-add and the paste.
 */
@Component
public class LateEntries {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final Audit audit;

    public LateEntries(PeriodRepository periods, ClaimRepository claims, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.audit = audit;
    }

    public void mark(Claim claim, Person person, String user) {
        if (periods.softClosedOn(claim.sheetId(), claim.dueBy()) == null) {
            return;
        }
        claims.markLateEntry(claim);
        audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date());
    }
}

